size_t encode(const PresenceHello &v, fr::wire::Writer &w)
{
    const size_t start = w.size();
    if (!v.mac.empty()) {
        w.field_bytes(1, v.mac);
    }
    if (v.chip != 0) {
        w.field_uint(2, v.chip);
    }
    if (v.chip_rev != 0) {
        w.field_uint(3, v.chip_rev);
    }
    if (!v.fw_id_prefix.empty()) {
        w.field_bytes(4, v.fw_id_prefix);
    }
    if (v.descriptor_hash != 0) {
        w.field_uint(5, v.descriptor_hash);
    }
    if (v.board_hash != 0) {
        w.field_uint(6, v.board_hash);
    }
    if (v.role != Role{}) {
        w.field_uint(7, std::to_underlying(v.role));
    }
    if (v.caps != 0) {
        w.field_uint(8, v.caps);
    }
    if (v.hb_interval_ms != 0) {
        w.field_uint(9, v.hb_interval_ms);
    }
    if (v.reset_reason != 0) {
        w.field_uint(10, v.reset_reason);
    }
    if (v.ota_state != OtaState{}) {
        w.field_uint(11, std::to_underlying(v.ota_state));
    }
    if (!v.alias.empty()) {
        w.field_string(12, v.alias);
    }
    if (v.alias_rev != 0) {
        w.field_uint(13, v.alias_rev);
    }
    if (v.channel != 0) {
        w.field_uint(14, v.channel);
    }
    if (!v.bssid.empty()) {
        w.field_bytes(15, v.bssid);
    }
    return w.size() - start;
}

